import{z as s,x as A,o as E,c as B,q as o,j as i,D as e,d as l,s as p,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"晶圆厂资本开支","description":"","frontmatter":{"title":"晶圆厂资本开支","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fab-capex.md","filePath":"litho/fab-capex.md","lastUpdated":1791063341000}'),d={name:"litho/fab-capex.md"};function c(h,a,m,x,f,D){const r=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="晶圆厂资本开支" tabindex="-1">晶圆厂资本开支 <a class="header-anchor" href="#晶圆厂资本开支" aria-label="Permalink to &quot;晶圆厂资本开支&quot;">​</a></h1><div class="epigraph"><p>先进逻辑厂的资本开支里，光刻设备占很大一截，但不是全部：洁净室、电源、真空、刻蚀与计量一起付款。</p><footer>—— 对照领先晶圆厂 capex 结构的公开产业讨论；不编造某厂亿美元数</footer></div><p><a href="/litho/capacity-planning-bottleneck">上一课</a>数了瓶颈台数。缺口是整张支票。本课钉晶圆厂资本开支。摩尔叙事如何从光刻视角阅读，留给<a href="/litho/moore-litho-view">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Capex = 厂房 + 设施（电、水、超纯、真空、排气）+ 设备（光刻、刻蚀、薄膜、CMP、检测、植入）。EUV 还要源、氢、锡、特殊真空。高 NA 再加更大的工具与设施接口。光刻占比高，但把 capex 全写成「ASML 发票」会漏掉设施与配套。周期：建设年与设备安装年的现金流不同，规划课的台数是峰值工具，不是第一年就全部到齐。</p><p><span class="marginnote">超纯水是电阻率逼近理论极限（约 18 MΩ·cm）的水：杂质离子少到几乎不导电，普通自来水的一滴都足以毁掉一批晶圆的清洗。水电、洁净室、排气这些「隐形基建」在 capex 里占的份量，常比外人想象的大得多。</span></p><p>缺口是<strong>整厂支票</strong>，不是单机折旧公式。不引用未核实的「某厂 200 亿美元」当定律。</p><h3 id="光刻占比随节点变" tabindex="-1">光刻占比随节点变 <a class="header-anchor" href="#光刻占比随节点变" aria-label="Permalink to &quot;光刻占比随节点变&quot;">​</a></h3><p>迁 EUV 提高光刻份额；3D NAND 把份额推向刻蚀（后课）。逻辑与存储的 capex 结构不同，不能用一个百分比。</p><p><span class="marginnote">出口管制与交货期会把 capex 计划变成「有钱买不到」——供应链课将展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>情景：目标 wpm × 瓶颈台数 × 单价 + 设施因子。灵敏度：EUV 层数、高 NA 插入年。与折旧：capex 是现金；折旧是后续晶圆成本。两者都要看，对象不同。</p><p><span class="marginnote">把开 Fab 想成开一家米其林餐厅：灶台（光刻机）最贵上镜，但水管、电路、冷库（超纯水、电源、洁净室）一样不能省。只盯灶台的发票，永远算不出整家店的开业支票——这就是本课要看的「整厂支票」。</span></p>',13)),(E(),i(n,null,{default:e(()=>[p(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%9B%AE%E6%A0%87%E4%BA%A7%E8%83%BD%20wpm%22%5D%20--%3E%20T%5B%22%E7%93%B6%E9%A2%88%E5%8F%B0%E6%95%B0%20(%E5%85%89%E5%88%BB)%22%5D%0A%20%20P%5B%22%E5%8D%95%E5%8F%B0%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20EQ%5B%22%E8%AE%BE%E5%A4%87%E6%94%AF%E7%A5%A8%22%5D%0A%20%20EQ%20--%3E%20F%5B%22%E4%B9%98%E8%AE%BE%E6%96%BD%E5%9B%A0%E5%AD%90%22%5D%0A%20%20F%20--%3E%20CAP%5B%22%E6%95%B4%E5%8E%82%20capex%22%5D%0A%20%20SEN%5B%22EUV%20%E5%B1%82%E6%95%B0%20%2F%20%E9%AB%98%20NA%20%E5%AF%BC%E5%85%A5%E5%B9%B4%22%5D%20--%3E%7C%E7%81%B5%E6%95%8F%E5%BA%A6%7C%20T%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"这张图回答的是：整厂支票怎么从产能目标推出来——产能定台数、台数乘单价、再乘设施因子，EUV 层数与高 NA 是两条最敏感的旋钮。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"固定成本极高导致必须规模：小厂摊不进先进光刻。这是代工集中的资本原因之一，不完全是技术秘密。",-1)),(E(),i(n,null,{default:e(()=>[p(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOOL%5B%22%E5%85%89%E5%88%BB%20%2B%20%E9%85%8D%E5%A5%97%E8%AE%BE%E5%A4%87%22%5D%20--%3E%20CAP%5B%22Fab%20capex%22%5D%0A%20%20FAC%5B%22%E5%8E%82%E6%88%BF%E8%AE%BE%E6%96%BD%22%5D%20--%3E%20CAP%0A%20%20CAP%20--%3E%20SCALE%5B%22%E8%A7%84%E6%A8%A1%E9%97%A8%E6%A7%9B%22%5D%0A%20%20SCALE%20--%3E%20CONC%5B%22%E4%BA%A7%E8%83%BD%E9%9B%86%E4%B8%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给投资建议。不把 capex 当运营成本。各国补贴改变谁付支票，不改变物理台数。</p><p><span class="marginnote">初学者容易把 capex 当成「买机器的一次性钱」然后忘掉。capex 是建设与装机年份的现金流出，之后通过多年折旧摊进每片晶圆的成本；把现金压力和单片成本混为一谈，会同时误判公司的现金流与产品的真实成本。</span></p><p>后课默认：先进光刻有规模门槛；下一课用摩尔定律的光刻读法看为什么支票越来越大仍在开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fab capex 含水电厂房与全套设备，光刻是大头但非全部。</li><li>逻辑与存储结构不同；EUV/高 NA 抬光刻份额。</li><li>规模门槛推动产能集中。</li><li>出处：晶圆厂 capex 结构的公开产业讨论。</li></ul>',6))])}const _=s(d,[["render",c]]);export{b as __pageData,_ as default};
